{
  "findings": [
    {
      "check_id": "CKV2_AWS_40",
      "title": "Ensure AWS IAM policy does not allow full IAM privileges",
      "resource": "aws_iam_policy.privesc-sageMakerCreatePresignedNotebookURL-policy",
      "severity": "MEDIUM",
      "explanation": "The IAM policy allows '*' as Resource for 'sagemaker:CreatePresignedNotebookInstanceUrl' and 'sagemaker:ListNotebookInstances' actions, potentially granting excessive permissions."
    }
  ],
  "patched_code": "resource "aws_iam_policy" "privesc-sageMakerCreatePresignedNotebookURL-policy" {
  name        = "privesc-sageMakerCreatePresignedNotebookURL-policy"
  path        = "/"
  description = "Allows privesc via sagemakerCreatePresignedNotebookURL"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action = [
          "sagemaker:CreatePresignedNotebookInstanceUrl",
          "sagemaker:ListNotebookInstances"
        ]
        Resource = "arn:aws:sagemaker:*:*:notebook-instance/*"
      },
    ]
  })
}",
  "fix_summary": "Restricted the Resource field in the IAM policy to a more specific ARN for SageMaker notebook instances to reduce excessive permissions."
}
